/**
 * Prompts: a few ways in, for a person who has installed the server and is looking at an empty
 * message box.
 *
 * The tools answer questions, but nothing told a new user which questions were worth asking. A
 * client lists these by `title`, and choosing one sends its text as the user's own message.
 *
 * Each text names the tools to start from and leaves the rest to the server's instructions, which
 * every client already has. A second copy of those rules here would be free to disagree with them.
 */

const ACCOUNT = 'Read my account with `decode_save` (leave `path` out to use the export found on this computer). '
  + 'If no export is found, tell me how to make one in the game and where to point the server at it, then stop.'

export const PROMPTS = {
  review_my_account: {
    title: 'Review my account',
    description: 'Read the game export and summarise where the account stands.',
    text: () => [
      'Review my account in The Tower.',
      '',
      ACCOUNT,
      'Then use `next_unlocks`, `coin_bonus` and `battle_history` for what opens next, where my coins come from and how my recent runs went.',
      'Summarise where the account stands, what is strong and what is behind. Take every number from a tool result, and say so when a tool could not answer.',
    ].join('\n'),
  },
  what_to_upgrade_next: {
    title: 'What should I upgrade next?',
    description: 'Rank the next few upgrades for the account, with what each costs.',
    arguments: [
      { name: 'goal', description: 'What you are playing for, e.g. "more coins per hour" or "a higher tournament rank".', required: false },
    ],
    text: ({ goal }) => [
      `What should I upgrade next in The Tower${String(goal ?? '').trim() ? `? My goal: ${String(goal).trim()}.` : '?'}`,
      '',
      ACCOUNT,
      'Use `next_unlocks` for what I can open and what it costs, and price anything else with the calculators (`calc_list`, `calc_describe`, `calc_run`) rather than from memory.',
      'Before recommending anything that cannot be undone, check `oracle_footguns`.',
      'Give me a short ranked list: what to buy, what it costs, and why it comes before the next one.',
    ].join('\n'),
  },
  explain_a_mechanic: {
    title: 'Explain a mechanic',
    description: 'Explain how one part of the game works, from the wiki and the game data.',
    arguments: [
      { name: 'mechanic', description: 'The mechanic, upgrade or term, e.g. "Death Wave" or "eHP".', required: true },
    ],
    text: ({ mechanic }) => [
      `Explain how ${String(mechanic).trim()} works in The Tower.`,
      '',
      'Expand any acronym with `define_term` or `oracle_expand` first. Look it up with `oracle_search` and `oracle_get`, read the related pages with `wiki_search` and `wiki_page`, and check `patch_notes` for whether it changed recently.',
      'Tell me what it does, its units, what it interacts with, and where the sources disagree. Say which source each claim comes from.',
    ].join('\n'),
  },
}
